		function cleanupSceneResources(sceneToClean) {
			if (!sceneToClean) return;
			sceneToClean.traverse((child) => {
				if (child.isMesh) {
					if (child.geometry) {
						// Dispose BVH if present
						if (child.geometry.boundsTree) {
							child.geometry.boundsTree = null;
						}
						child.geometry.dispose();
					}
					if (child.material) {
						if (Array.isArray(child.material)) {
							child.material.forEach(material => disposeMaterial(material));
						} else {
							disposeMaterial(child.material);
						}
					}
				}
				if (child.isLine || child.isLineSegments) {
					if (child.geometry) child.geometry.dispose();
					if (child.material) disposeMaterial(child.material);
				}
			});
		}

		function disposeMaterial(material) {
			if (!material) return;
			Object.values(material).forEach(value => {
				if (value && value.isTexture) {
					value.dispose();
				}
			});
			if (material.uniforms) {
				Object.values(material.uniforms).forEach(uniform => {
					if (uniform.value && uniform.value.isTexture) {
						uniform.value.dispose();
					}
					if (uniform.value && uniform.value.isCubeTexture) {
						uniform.value.dispose();
					}
				});
			}

			material.dispose();
		}

		function cleanupDiamonds() {
			if (makeDiamond.sharedGeometry) {
				// Clear BVH
				if (makeDiamond.sharedGeometry.boundsTree) {
					makeDiamond.sharedGeometry.boundsTree = null;
				}
				makeDiamond.sharedGeometry.dispose();
				makeDiamond.sharedGeometry = null;
			}

			if (makeDiamond.sharedCollider) {
				if (makeDiamond.sharedCollider.geometry) {
					makeDiamond.sharedCollider.geometry.dispose();
				}
				if (makeDiamond.sharedCollider.material) {
					disposeMaterial(makeDiamond.sharedCollider.material);
				}
				makeDiamond.sharedCollider = null;
			}

			if (makeDiamond.sharedBVH) {
				makeDiamond.sharedBVH = null;
			}

			if (makeDiamond.staticMaterial) {
				disposeMaterial(makeDiamond.staticMaterial);
				makeDiamond.staticMaterial = null;
			}

			if (makeDiamond.wireframeMaterial) {
				disposeMaterial(makeDiamond.wireframeMaterial);
				makeDiamond.wireframeMaterial = null;
			}
		}

