		// function to smooth reset the OrbitControl camera's angles
		function doSmoothReset() {
			// Desired final tilt angles
			const targetAlpha = 0.00; // slight horizontal tilt (azimuthal)
			const targetBeta = -0.25; // slight vertical tilt (polar)
			const defaultDistance = 23; // Set your desired default zoom
			const lerpFactor = 0.999;
			const defaultTarget = new THREE.Vector3(0, -3, 0);
			const defaultCameraPosition = new THREE.Vector3(0.16049332246694262, 2.830024467318552, 22.519828131435272);
			// get current angles
			let alpha = controls.getAzimuthalAngle(),
				beta = controls.getPolarAngle() - Math.PI / 2;
			// Lerp angles towards target tilt
			alpha = lerpFactor * alpha + (1 - lerpFactor) * targetAlpha;
			beta = lerpFactor * beta + (1 - lerpFactor) * targetBeta;
			// if they are close to the reset values, just set these values
			if (Math.abs(alpha - targetAlpha) < 0.001) alpha = targetAlpha;
			if (Math.abs(beta - targetBeta) < 0.001) beta = targetBeta;
			// smooth change using manual lerp
			controls.minAzimuthAngle = alpha;
			controls.maxAzimuthAngle = controls.minAzimuthAngle;
			controls.minPolarAngle = Math.PI / 2 + beta;
			controls.maxPolarAngle = controls.minPolarAngle;
			// Restore target
			controls.target.lerp(defaultTarget, 1 - lerpFactor);
			// Restore camera position
			camera.position.lerp(defaultCameraPosition, 1 - lerpFactor);
			// Restore zoom
			// Lerp camera position towards default distance from controls.target
			const direction = new THREE.Vector3().subVectors(camera.position, controls.target).normalize();
			const currentDistance = camera.position.distanceTo(controls.target);
			const newDistance = lerpFactor * currentDistance + (1 - lerpFactor) * defaultDistance;
			camera.position.copy(controls.target).add(direction.multiplyScalar(newDistance));

			const targetSliderPos = window.innerWidth / 2;
			if (timer > 489) {
				if (slider.style.opacity == 0) {
					fadein([slider]);
				}
				sliderPos = lerpFactor * sliderPos + (1 - lerpFactor) * targetSliderPos;
				if (slider) {
					slider.style.left = sliderPos - (slider.offsetWidth / 2) + 'px';
					// Update ARIA attributes
					slider.setAttribute('aria-valuenow', sliderPos);
					// Update aria-valuetext for a more descriptive read-out
					const percentage = Math.round((sliderPos / window.innerWidth) * 100);
					slider.setAttribute('aria-valuetext', `Left panel ${percentage} percent, Right panel ${100 - percentage} percent`);
				}
			}
			// if the reset values are reached, exit smooth reset
			if (Math.abs(alpha - targetAlpha) < 0.001 &&
				Math.abs(beta - targetBeta) < 0.001 &&
				Math.abs(currentDistance - defaultDistance) < 0.01 &&
				camera.position.distanceTo(defaultCameraPosition) < 0.01 &&
				controls.target.distanceTo(defaultTarget) < 0.01 &&
				Math.abs(sliderPos - targetSliderPos) < 1
			) {
				camera.position.copy(defaultCameraPosition);
				controls.target.copy(defaultTarget);
				onStart();
				smoothReset = false;
				timer = 0;
			}
		}
		function updateIntroAnimation() {
			if (!QParent) return;
			if (introAnimationState.phase === 'rotating') {
				// Y-axis rotation (1 full revolutions = 2π radians)
				Pivot.rotation.y += introAnimationState.rotationSpeed;
				introAnimationState.rotationProgress += introAnimationState.rotationSpeed;
				if (introAnimationState.rotationProgress >= Math.PI * 2) {
					introAnimationState.phase = 'tilting';
				}
            } else if (introAnimationState.phase === 'tilting') {
                // Z-axis tilt back to 0 from 136 degrees
                const targetZ = 0;
                const currentZ = Pivot.rotation.z;
                const diff = targetZ - currentZ;

                if (Math.abs(diff) > 0.005) {
                    const startZ = THREE.MathUtils.degToRad(136);
                    const totalDistance = Math.abs(startZ - targetZ); // Total distance to travel
                    const distanceTraveled = Math.abs(startZ - currentZ);
                    const progress = distanceTraveled / totalDistance; // 0 to 1
                    const easeInOut = progress < 0.5 ?
                        7 * Math.pow(progress, 5) :
                        7 * Math.pow(0.5 - (progress - 0.5), 5);
                    const speed = introAnimationState.rotationSpeed * (0.6 + easeInOut * 1.2); // base speed + eased component
                    Pivot.rotation.z += Math.sign(diff) * speed;
                } else {
                    Pivot.rotation.z = targetZ;
                    introAnimationState.phase = 'complete';
                }
			} else if (introAnimationState.phase === 'complete') {
				isInitialAnimationComplete = true;
				initializeStage2Obj();
				fadeInGroup();
				initializeHelpersStaggered();
				optimizeForSafari();
			}
		}

		function setGroupOpacity(group, opacity) {
			group.traverse((child) => {
				if (child.isMesh) {
					child.material.transparent = true;
					child.material.opacity = opacity;
				}
			});
		}
		let currentOpacity = 0;
		const fadeInGroup = () => {
			doSmoothReset();
			if (currentOpacity < 1) {
				currentOpacity += 0.001; // Adjust increment for speed
				setGroupOpacity(loadingStage2Obj, currentOpacity);
				requestAnimationFrame(fadeInGroup);
			}
		};

		function fadein(elements) {
			const fadeInDuration = 1000; // Duration in milliseconds
			const startTime = Date.now();
			controls.enabled = true;

			function fade() {
				const elapsed = Date.now() - startTime;
				// Ease-out cubic for smoother finish
				const t = Math.min(elapsed / fadeInDuration, 1);
				const opacity = Math.pow(t, 3); // Ease-in cubic
				elements.forEach(element => {
					element.style.opacity = opacity;
				});
				if (t < 1) {
					requestAnimationFrame(fade);
				}
			}

			fade();
		}

		function fadeout() {
			const fadeOutDuration = 500; // Duration in milliseconds
			const startTime = Date.now();
			controls.enabled = false;


			function fade() {
				const elapsed = Date.now() - startTime;
				// Ease-out cubic for smoother finish
				const t = Math.min(elapsed / fadeOutDuration, 1);
				const opacity = 1 - Math.pow(1 - t, 3);
				canvas.style.opacity = 1 - opacity; // Fade out the canvas
				viewHelperPanel.style.opacity = 1 - opacity;
				ringHelperPanel.style.opacity = 1 - opacity;
				if (t < 1) {
					requestAnimationFrame(fade);
				} else {
					renderer.clear(); // Clear the renderer after fade out
					gimbalRenderer.clear();
					ringRenderer.clear();
				}
			}
			fade();
		}

